def fizz_buzz(n: int):
    def has_seven(num):
        return '7' in str(num)

    def is_divisible_by_11_or_13(num):
        return num % 11 == 0 or num % 13 == 0

    count = 0
    for i in range(1, n):
        if has_seven(i) and is_divisible_by_11_or_13(i):
            count += 1

