def separate_paren_groups(paren_string: str) -> List[str]:
    def remove_spaces(s):
        return s.replace(" ", "")

    def extract_groups(s):
        stack = []
        groups = []
        current_group = ""

        for char in s:
            if char == "(":
                stack.append(char)
            elif char == ")":
                stack.pop()
                if not stack:
                    groups.append(current_group)
                    current_group = ""
            else:
                if stack:
                    current_group += char

        return groups

    paren_string = remove_spaces(paren_string)
    groups = extract_groups(paren_string)

    return groups

