    if n < 0 or p <= 0:
        return None

    if n == 0:
        return 1 % p

    result = 1
    base = 2 % p
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        n = n // 2
        base = (base * base) % p

    return result
